import { chromium } from 'playwright';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
const root = '/Users/raedmohammed/RaedWorkoutsV2/worktree-v16';
const appUrl = pathToFileURL(path.join(root,'index.html')).href;
const user = 'ar-audit';
const state = {
  schema_version: 2, programme_reference_migration_version: 1,
  current_week: 1, current_block: 1,
  profile: { display_name: 'اختبار', experience: 'returning', created_at: '2026-08-25T00:00:00.000Z' },
  active_session: null, history: [], bodyweight_log: [{date:'2026-09-01', kg:82.5}],
  custom_videos:{}, custom_jn_urls:{}, video_hidden:{}, custom_exercises:[],
  programme_overrides:null, prs:{}, msg_index:0, substitutions:[],
};
const settings = { user_id:user, user_key:'', theme:'light', skin:'hadid', focus_mode:true, show_cues:true,
  rest_seconds:120, vibrate:false, notifications:false, music_platform:'none', block_auto_color:false,
  block_skin_suggestions:{}, block_skin_rejections:{}, lang:'ar', locale_version:1, runner_video_open:true };
const b = await chromium.launch({args:['--allow-file-access-from-files']});
const p = await b.newPage({ viewport:{width:390,height:844} });
await p.route('https://**/*', r=>r.abort());
await p.addInitScript(({user,state,settings})=>{
  localStorage.clear();
  localStorage.setItem('raedworkouts.active_user', user);
  localStorage.setItem(`raedworkouts.${encodeURIComponent(user)}.state.v1`, JSON.stringify(state));
  localStorage.setItem(`raedworkouts.${encodeURIComponent(user)}.settings.v1`, JSON.stringify(settings));
},{user,state,settings});
await p.goto(appUrl,{waitUntil:'domcontentloaded'});
await p.waitForTimeout(1000);
await p.locator('.tab[data-route="history"]').click();
await p.waitForTimeout(400);
console.log('=== HISTORY ===');
console.log(await p.evaluate(()=>document.querySelector('#page-history').innerText));
// visual order of the "Latest" line
console.log('LATEST-LINE HTML:', await p.evaluate(()=>{
  const n=[...document.querySelectorAll('#page-history .tiny.muted')].map(e=>e.outerHTML); return n.join('\n');
}));
// end screen
await p.evaluate(()=>{ location.hash='end'; });
await p.waitForTimeout(500);
console.log('=== END (cold) ===');
console.log(await p.evaluate(()=>document.querySelector('#page-end').innerText));
// warm-up screen: treadmill copy visual order
await p.evaluate(()=>{ location.hash='home'; });
await p.waitForTimeout(300);
await p.locator('#page-home button.btn.primary.full').first().click();
await p.waitForTimeout(500);
console.log('=== WARMUP visual order of choose_treadmill ===');
console.log(await p.evaluate(()=>{
  const el=[...document.querySelectorAll('#page-home .warmup-phase .tiny.muted')].find(e=>/دقائق/.test(e.textContent));
  if(!el) return '(not found) ' + document.querySelector('#page-home .warmup-phase')?.innerText;
  const parts=[];
  for(const n of el.childNodes){ const r=document.createRange(); r.selectNode(n); const b=r.getBoundingClientRect(); parts.push({t:n.textContent,x:Math.round(b.x)}); }
  return 'SOURCE: '+el.textContent+'\nVISUAL(left→right): '+parts.filter(q=>q.t.trim()).sort((a,c)=>a.x-c.x).map(q=>q.t.trim()).join(' | ')+'\nHTML: '+el.outerHTML;
}));
await b.close();
